package main
import("flag";"log";"time"; cfg "mortify-crm-agent/internal/config"; "mortify-crm-agent/internal/collector"; "mortify-crm-agent/internal/sender"; "mortify-crm-agent/internal/scheduler")
type Metrics struct{CPUPercent float64 `json:"cpuPercent"`; MemoryPercent float64 `json:"memoryPercent"`; DiskPercent float64 `json:"diskPercent"`; UptimeSeconds uint64 `json:"uptimeSeconds"`; ProcessCount int `json:"processCount"`}
type Checks struct{Processes []collector.CheckResult `json:"processes"`; Services []collector.CheckResult `json:"services"`}
type Payload struct{AssetID string `json:"assetId"`; Hostname string `json:"hostname"`; OS collector.OSInfo `json:"os"`; Network collector.NetworkInfo `json:"network"`; Metrics Metrics `json:"metrics"`; Checks Checks `json:"checks"`; CollectedAt string `json:"collectedAt"`}
func collect(c cfg.Config)Payload{return Payload{AssetID:c.AssetID,Hostname:collector.Hostname(),OS:collector.OS(),Network:collector.Network(),Metrics:Metrics{collector.CPUPercent(),collector.MemoryPercent(),collector.DiskPercent(),collector.Uptime(),collector.ProcessCount()},Checks:Checks{collector.Processes(c.ProcessChecks),collector.Services(c.ServiceChecks)},CollectedAt:time.Now().UTC().Format(time.RFC3339)}}
func main(){path:=flag.String("config","config.yaml","config path"); flag.Parse(); c,err:=cfg.Load(*path); if err!=nil{log.Fatal(err)}; client:=sender.New(c.APIURL,c.Token,c.VerifyTLS); scheduler.Every(c,func(){p:=collect(c); for i:=0;i<3;i++{if err:=client.Post("/agent/metrics",p); err==nil{return}; log.Printf("send failed attempt %d",i+1); time.Sleep(time.Duration(i+1)*time.Second)}})}
